/// Provenance of a memory item.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum MemorySource {
    TapeUserMessage,
    TapeToolResult,
    Summary,
    Manual,
    Import,
}

impl MemorySource {
    /// Returns the canonical string persisted in SQLite and used in API payloads.
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::TapeUserMessage => "tape:user_message",
            Self::TapeToolResult => "tape:tool_result",
            Self::Summary => "summary",
            Self::Manual => "manual",
            Self::Import => "import",
        }
    }

    /// Parses the persisted string form; returns `None` for unknown values.
    pub fn from_str(value: &str) -> Option<Self> {
        match value {
            "tape:user_message" => Some(Self::TapeUserMessage),
            "tape:tool_result" => Some(Self::TapeToolResult),
            "summary" => Some(Self::Summary),
            "manual" => Some(Self::Manual),
            "import" => Some(Self::Import),
            _ => None,
        }
    }
}

