#[derive(Debug, Clone)]
struct StartupResumeCandidate {
    run_id: String,
    session_id: String,
    previous_state: String,
    parent_run_id: Option<String>,
    principal: String,
    device_id: String,
    channel: Option<String>,
    origin_kind: String,
}

fn startup_resume_classifier_input(
    connection: &Connection,
    candidate: &StartupResumeCandidate,
    now: i64,
) -> Result<(ResumeClassifierInput, ReplayTranscriptSignals), JournalError> {
    let observations = load_resume_tape_observations(connection, candidate.run_id.as_str())?;
    let signals = summarize_resume_tape_observations(observations.as_slice());
    let replay_transcript_signals =
        summarize_replay_transcript_observations(observations.as_slice());
    let final_output_exists = connection.query_row(
        "SELECT EXISTS(SELECT 1 FROM runtime_final_output_artifacts WHERE run_ulid = ?1)",
        params![candidate.run_id.as_str()],
        |row| row.get::<_, bool>(0),
    )?;
    Ok((
        ResumeClassifierInput {
            run_id: candidate.run_id.clone(),
            session_id: candidate.session_id.clone(),
            // A committed final artifact is terminal even when the legacy run
            // row still says active. Recovery may finish delivery, but must not
            // regenerate already-persisted output.
            run_state: if final_output_exists {
                "done".to_owned()
            } else {
                candidate.previous_state.clone()
            },
            run_principal: candidate.principal.clone(),
            // Startup recovery is host-owned and uses the persisted session
            // authority. Supplying that exact authority makes SafeToResume
            // reachable without accepting a caller-selected identity.
            reconnect_principal: Some(candidate.principal.clone()),
            run_channel: candidate.channel.clone(),
            reconnect_channel: candidate.channel.clone(),
            channel_exists: candidate
                .channel
                .as_deref()
                .is_none_or(|channel| !channel.trim().is_empty()),
            observed_at_unix_ms: now,
            max_freshness_age_ms: DEFAULT_RESUME_FRESHNESS_TTL_MS,
            last_transcript_event_unix_ms: signals.last_transcript_event_unix_ms,
            last_model_turn_unix_ms: signals.last_model_turn_unix_ms,
            mutating_tool_in_flight: signals.mutating_tool_in_flight,
            read_only_tool_wait: signals.read_only_tool_wait,
            pending_approval: signals.pending_approval,
            routine_lease_active: matches!(candidate.origin_kind.as_str(), "routine" | "cron"),
            workspace_mutation_checkpoint_clean: signals.workspace_mutation_checkpoint_clean,
        },
        replay_transcript_signals,
    ))
}

fn load_resume_tape_observations(
    connection: &Connection,
    run_id: &str,
) -> Result<Vec<ResumeTapeObservation>, JournalError> {
    let mut statement = connection.prepare(
        r#"
            SELECT event_type, payload_json, created_at_unix_ms
            FROM orchestrator_tape
            WHERE run_ulid = ?1
            ORDER BY seq ASC
        "#,
    )?;
    let rows = statement.query_map(params![run_id], |row| {
        Ok(ResumeTapeObservation {
            event_type: row.get(0)?,
            payload_json: row.get(1)?,
            created_at_unix_ms: row.get(2)?,
        })
    })?;
    rows.collect::<Result<Vec<_>, _>>().map_err(JournalError::from)
}

fn next_orchestrator_tape_seq(connection: &Connection, run_id: &str) -> Result<i64, JournalError> {
    connection
        .query_row(
            "SELECT COALESCE(MAX(seq), -1) + 1 FROM orchestrator_tape WHERE run_ulid = ?1",
            params![run_id],
            |row| row.get::<_, i64>(0),
        )
        .map_err(Into::into)
}

fn append_orchestrator_tape_event_tx(
    connection: &Connection,
    max_payload_bytes: usize,
    request: &OrchestratorTapeAppendRequest,
    now: i64,
) -> Result<(), JournalError> {
    let payload_json = sanitize_orchestrator_tape_payload(request, max_payload_bytes)?;
    insert_orchestrator_tape_event_tx(connection, request, payload_json.as_str(), now)
}

fn append_or_replay_orchestrator_tape_event_tx(
    connection: &Connection,
    max_payload_bytes: usize,
    request: &OrchestratorTapeAppendRequest,
    now: i64,
) -> Result<(), JournalError> {
    let payload_json = sanitize_orchestrator_tape_payload(request, max_payload_bytes)?;
    let existing = connection
        .query_row(
            r#"
                SELECT event_type, payload_json
                FROM orchestrator_tape
                WHERE run_ulid = ?1 AND seq = ?2
            "#,
            params![request.run_id, request.seq],
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
        )
        .optional()?;
    match existing {
        Some((event_type, existing_payload_json))
            if event_type == request.event_type && existing_payload_json == payload_json =>
        {
            Ok(())
        }
        Some(_) => Err(JournalError::DuplicateTapeSequence {
            run_id: request.run_id.clone(),
            seq: request.seq,
        }),
        None => insert_orchestrator_tape_event_tx(connection, request, payload_json.as_str(), now),
    }
}

fn sanitize_orchestrator_tape_payload(
    request: &OrchestratorTapeAppendRequest,
    max_payload_bytes: usize,
) -> Result<String, JournalError> {
    if request.payload_json.len() > max_payload_bytes {
        return Err(JournalError::PayloadTooLarge {
            payload_kind: "orchestrator_tape",
            actual_bytes: request.payload_json.len(),
            max_bytes: max_payload_bytes,
        });
    }
    sanitize_payload(request.payload_json.as_bytes()).map(|(payload_json, _)| payload_json)
}

fn insert_orchestrator_tape_event_tx(
    connection: &Connection,
    request: &OrchestratorTapeAppendRequest,
    payload_json: &str,
    now: i64,
) -> Result<(), JournalError> {
    match connection.execute(
        r#"
            INSERT INTO orchestrator_tape (
                run_ulid,
                seq,
                event_type,
                payload_json,
                created_at_unix_ms
            ) VALUES (?1, ?2, ?3, ?4, ?5)
        "#,
        params![request.run_id, request.seq, request.event_type, payload_json, now],
    ) {
        Ok(_) => Ok(()),
        Err(rusqlite::Error::SqliteFailure(error, message))
            if error.code == ErrorCode::ConstraintViolation
                && (error.extended_code == rusqlite::ffi::SQLITE_CONSTRAINT_PRIMARYKEY
                    || error.extended_code == rusqlite::ffi::SQLITE_CONSTRAINT_UNIQUE
                    || message
                        .as_deref()
                        .is_some_and(|value| value.contains("orchestrator_tape"))) =>
        {
            Err(JournalError::DuplicateTapeSequence {
                run_id: request.run_id.clone(),
                seq: request.seq,
            })
        }
        Err(error) => Err(error.into()),
    }
}

fn hydrate_run_lifecycle_record(
    row: &rusqlite::Row<'_>,
) -> rusqlite::Result<RunLifecycleTransitionRecord> {
    let from_state: Option<String> = row.get(3)?;
    let to_state: String = row.get(4)?;
    let actor_kind: String = row.get(5)?;
    Ok(RunLifecycleTransitionRecord {
        schema_version: 1,
        event_id: row.get(0)?,
        run_id: row.get(1)?,
        session_id: row.get(2)?,
        from_state: from_state.as_deref().and_then(RunLifecyclePhase::parse),
        to_state: RunLifecyclePhase::parse(to_state.as_str()).ok_or_else(|| {
            rusqlite::Error::FromSqlConversionFailure(
                4,
                rusqlite::types::Type::Text,
                Box::new(std::io::Error::other(format!("unknown run lifecycle state: {to_state}"))),
            )
        })?,
        actor: RuntimeActorRef {
            kind: RuntimeActorKind::parse(actor_kind.as_str()).ok_or_else(|| {
                rusqlite::Error::FromSqlConversionFailure(
                    5,
                    rusqlite::types::Type::Text,
                    Box::new(std::io::Error::other(format!(
                        "unknown runtime actor kind: {actor_kind}"
                    ))),
                )
            })?,
            id: row.get(6)?,
        },
        correlation_id: row.get(7)?,
        parent_run_id: row.get(8)?,
        idempotency_key: row.get(9)?,
        reason: row.get(10)?,
        occurred_at_unix_ms: row.get(11)?,
    })
}

fn load_idempotency_record(
    connection: &Connection,
    key: &str,
) -> Result<Option<IdempotencyRecordSnapshot>, JournalError> {
    connection
        .query_row(
            r#"
                SELECT
                    idempotency_key,
                    scope,
                    operation_kind,
                    payload_sha256,
                    state,
                    result_json,
                    error_json,
                    first_seen_at_unix_ms,
                    updated_at_unix_ms,
                    expires_at_unix_ms
                FROM idempotency_records
                WHERE idempotency_key = ?1
            "#,
            params![key],
            hydrate_idempotency_record,
        )
        .optional()
        .map_err(JournalError::from)
}

fn hydrate_idempotency_record(
    row: &rusqlite::Row<'_>,
) -> rusqlite::Result<IdempotencyRecordSnapshot> {
    let raw_state: String = row.get(4)?;
    let raw_error: Option<String> = row.get(6)?;
    Ok(IdempotencyRecordSnapshot {
        key: row.get(0)?,
        scope: row.get(1)?,
        operation_kind: row.get(2)?,
        payload_sha256: row.get(3)?,
        state: IdempotencyOperationState::parse(raw_state.as_str()).ok_or_else(|| {
            rusqlite::Error::FromSqlConversionFailure(
                4,
                rusqlite::types::Type::Text,
                Box::new(std::io::Error::other(format!("unknown idempotency state: {raw_state}"))),
            )
        })?,
        result_json: row.get(5)?,
        error: raw_error
            .as_deref()
            .map(serde_json::from_str::<StableErrorEnvelope>)
            .transpose()
            .map_err(|error| {
                rusqlite::Error::FromSqlConversionFailure(
                    6,
                    rusqlite::types::Type::Text,
                    Box::new(error),
                )
            })?,
        first_seen_at_unix_ms: row.get(7)?,
        updated_at_unix_ms: row.get(8)?,
        expires_at_unix_ms: row.get(9)?,
    })
}

fn hydrate_compat_response_record(
    row: &rusqlite::Row<'_>,
) -> rusqlite::Result<CompatResponseRecord> {
    Ok(CompatResponseRecord {
        response_id: row.get(0)?,
        session_id: row.get(1)?,
        run_id: row.get(2)?,
        owner_principal: row.get(3)?,
        device_id: row.get(4)?,
        channel: row.get(5)?,
        status: row.get(6)?,
        response_json: row.get(7)?,
        error_json: row.get(8)?,
        redaction_state_json: row.get(9)?,
        created_at_unix_ms: row.get(10)?,
        completed_at_unix_ms: row.get(11)?,
        updated_at_unix_ms: row.get(12)?,
        retention_expires_at_unix_ms: row.get(13)?,
        deleted_at_unix_ms: row.get(14)?,
        delete_reason: row.get(15)?,
    })
}

fn load_compat_response_record(
    connection: &Connection,
    response_id: &str,
) -> Result<Option<CompatResponseRecord>, JournalError> {
    connection
        .query_row(
            r#"
                SELECT
                    response_ulid,
                    session_ulid,
                    run_ulid,
                    owner_principal,
                    device_id,
                    channel,
                    status,
                    response_json,
                    error_json,
                    redaction_state_json,
                    created_at_unix_ms,
                    completed_at_unix_ms,
                    updated_at_unix_ms,
                    retention_expires_at_unix_ms,
                    deleted_at_unix_ms,
                    delete_reason
                FROM compat_response_records
                WHERE response_ulid = ?1
            "#,
            params![response_id],
            hydrate_compat_response_record,
        )
        .optional()
        .map_err(JournalError::from)
}

fn append_compat_response_event_tx(
    connection: &Connection,
    max_payload_bytes: usize,
    record: &CompatResponseRecord,
    event_type: &str,
    payload: Value,
    now: i64,
) -> Result<(), JournalError> {
    let raw_payload = payload.to_string();
    if raw_payload.len() > max_payload_bytes {
        return Err(JournalError::PayloadTooLarge {
            payload_kind: "compat_response_event",
            actual_bytes: raw_payload.len(),
            max_bytes: max_payload_bytes,
        });
    }
    let (payload_json, _) = sanitize_payload(raw_payload.as_bytes())?;
    connection.execute(
        r#"
            INSERT INTO compat_response_events (
                event_ulid,
                response_ulid,
                session_ulid,
                run_ulid,
                event_type,
                actor_principal,
                payload_json,
                created_at_unix_ms
            ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)
        "#,
        params![
            Ulid::new().to_string(),
            record.response_id,
            record.session_id,
            record.run_id,
            event_type,
            record.owner_principal,
            payload_json,
            now,
        ],
    )?;
    Ok(())
}

