const fn queued_input_transition_allowed(from: QueuedInputState, to: QueuedInputState) -> bool {
    match from {
        QueuedInputState::Pending | QueuedInputState::Deferred => matches!(
            to,
            QueuedInputState::Claimed
                | QueuedInputState::Deferred
                | QueuedInputState::Merged
                | QueuedInputState::Overflowed
                | QueuedInputState::Rejected
                | QueuedInputState::Cancelled
                | QueuedInputState::Superseded
        ),
        QueuedInputState::Claimed => matches!(
            to,
            QueuedInputState::Injected
                | QueuedInputState::Forwarded
                | QueuedInputState::DeliveryFailed
                | QueuedInputState::Deferred
                | QueuedInputState::Superseded
                | QueuedInputState::Cancelled
        ),
        QueuedInputState::Injected
        | QueuedInputState::Forwarded
        | QueuedInputState::DeliveryFailed
        | QueuedInputState::Merged
        | QueuedInputState::Steered
        | QueuedInputState::Interrupted
        | QueuedInputState::Superseded
        | QueuedInputState::Overflowed
        | QueuedInputState::Rejected
        | QueuedInputState::Cancelled => false,
    }
}

fn load_session_project_context_state(
    connection: &Connection,
    session_id: &str,
) -> Result<Option<SessionProjectContextStateRecord>, JournalError> {
    let mut statement = connection.prepare(
        r#"
            SELECT
                session_ulid,
                focus_paths_json,
                disabled_entry_ids_json,
                approved_entry_ids_json,
                last_refreshed_at_unix_ms,
                updated_at_unix_ms
            FROM session_project_context_state
            WHERE session_ulid = ?1
            LIMIT 1
        "#,
    )?;
    statement
        .query_row(params![session_id], |row| {
            Ok(SessionProjectContextStateRecord {
                session_id: row.get(0)?,
                focus_paths: serde_json::from_str(row.get::<_, String>(1)?.as_str())
                    .unwrap_or_default(),
                disabled_entry_ids: serde_json::from_str(row.get::<_, String>(2)?.as_str())
                    .unwrap_or_default(),
                approved_entry_ids: serde_json::from_str(row.get::<_, String>(3)?.as_str())
                    .unwrap_or_default(),
                last_refreshed_at_unix_ms: row.get(4)?,
                updated_at_unix_ms: row.get(5)?,
            })
        })
        .optional()
        .map_err(Into::into)
}

