fn empty_usage_timeline_bucket(
    query: &OrchestratorUsageQuery,
    index: usize,
) -> OrchestratorUsageTimelineBucket {
    let bucket_start_unix_ms =
        query.start_at_unix_ms.saturating_add(query.bucket_width_ms.saturating_mul(index as i64));
    OrchestratorUsageTimelineBucket {
        bucket_start_unix_ms,
        bucket_end_unix_ms: bucket_start_unix_ms.saturating_add(query.bucket_width_ms),
        runs: 0,
        session_count: 0,
        active_runs: 0,
        completed_runs: 0,
        prompt_tokens: 0,
        completion_tokens: 0,
        total_tokens: 0,
        average_latency_ms: None,
        estimated_cost_usd: None,
    }
}

fn usage_bucket_count(query: &OrchestratorUsageQuery) -> usize {
    let window =
        query.end_at_unix_ms.saturating_sub(query.start_at_unix_ms).max(query.bucket_width_ms);
    let quotient = window / query.bucket_width_ms;
    if window % query.bucket_width_ms == 0 {
        quotient as usize
    } else {
        quotient.saturating_add(1) as usize
    }
}

fn average_latency_from_row(
    row: &rusqlite::Row<'_>,
    index: usize,
) -> Result<Option<u64>, rusqlite::Error> {
    let value = row.get::<_, Option<f64>>(index)?;
    Ok(value.map(|latency| latency.max(0.0).round() as u64))
}

fn bool_to_sqlite(value: bool) -> i64 {
    if value {
        1
    } else {
        0
    }
}

/// Converts to `i64` for SQLite storage, failing with `InvalidArgument` instead
/// of wrapping when the value exceeds `i64::MAX`.
fn u64_to_sqlite(value: u64, field_name: &'static str) -> Result<i64, JournalError> {
    i64::try_from(value).map_err(|_| {
        rusqlite::Error::ToSqlConversionFailure(Box::new(std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            format!("{field_name} exceeds sqlite INTEGER range"),
        )))
        .into()
    })
}

/// Validates that `raw` parses as JSON.
fn ensure_json_field(raw: &str, field: &'static str) -> Result<(), JournalError> {
    serde_json::from_str::<Value>(raw).map(|_| ()).map_err(|error| {
        JournalError::InvalidArgument(format!("{field} must be valid JSON: {error}"))
    })
}

fn ensure_nonempty_field(raw: &str, field: &'static str) -> Result<(), JournalError> {
    if raw.trim().is_empty() {
        return Err(JournalError::InvalidArgument(format!("{field} cannot be empty")));
    }
    Ok(())
}

fn ensure_valid_work_item_state(state: &str) -> Result<(), JournalError> {
    if is_known_work_item_state(state) {
        Ok(())
    } else {
        Err(JournalError::InvalidArgument(format!("unknown work item state: {state}")))
    }
}

fn is_known_work_item_state(state: &str) -> bool {
    matches!(
        state,
        "queued"
            | "running"
            | "paused"
            | "blocked"
            | "waiting"
            | "succeeded"
            | "failed"
            | "cancel_requested"
            | "cancelled"
    )
}

fn ensure_work_item_parent_not_self(
    work_item_id: &str,
    parent_work_item_id: Option<&str>,
) -> Result<(), JournalError> {
    if parent_work_item_id.is_some_and(|parent| parent == work_item_id) {
        return Err(JournalError::InvalidArgument(
            "parent_work_item_id cannot reference the same work item".to_owned(),
        ));
    }
    Ok(())
}

fn ensure_valid_work_item_verification_state(state: &str) -> Result<(), JournalError> {
    if is_known_work_item_verification_state(state) {
        Ok(())
    } else {
        Err(JournalError::InvalidArgument(format!("unknown work item verification state: {state}")))
    }
}

fn is_known_work_item_verification_state(state: &str) -> bool {
    matches!(state, "unverified" | "pending" | "verified" | "failed" | "waived")
}

fn is_terminal_work_item_state(state: &str) -> bool {
    matches!(state, "succeeded" | "failed" | "cancelled")
}

fn validate_work_item_transition(
    work_item_id: &str,
    from: &str,
    to: &str,
) -> Result<(), JournalError> {
    ensure_valid_work_item_state(to)?;
    if from == to {
        return Ok(());
    }
    if is_terminal_work_item_state(from) {
        return Err(JournalError::InvalidWorkItemTransition {
            work_item_id: work_item_id.to_owned(),
            from: from.to_owned(),
            to: to.to_owned(),
        });
    }
    Ok(())
}

fn ensure_valid_commitment_status(status: &str) -> Result<(), JournalError> {
    if is_known_commitment_status(status) {
        Ok(())
    } else {
        Err(JournalError::InvalidArgument(format!("unknown commitment status: {status}")))
    }
}

fn is_known_commitment_status(status: &str) -> bool {
    matches!(
        status,
        "proposed" | "approved" | "scheduled" | "snoozed" | "delivered" | "dismissed" | "failed"
    )
}

fn is_terminal_commitment_status(status: &str) -> bool {
    matches!(status, "delivered" | "dismissed" | "failed")
}

fn validate_commitment_transition(
    commitment_id: &str,
    from: &str,
    to: &str,
) -> Result<(), JournalError> {
    ensure_valid_commitment_status(to)?;
    if from == to {
        return Ok(());
    }
    if is_terminal_commitment_status(from) {
        return Err(JournalError::InvalidCommitmentTransition {
            commitment_id: commitment_id.to_owned(),
            from: from.to_owned(),
            to: to.to_owned(),
        });
    }
    Ok(())
}

fn ensure_valid_agent_plan_status(status: &str) -> Result<(), JournalError> {
    if is_known_agent_plan_status(status) {
        Ok(())
    } else {
        Err(JournalError::InvalidArgument(format!("unknown agent plan status: {status}")))
    }
}

/// Validates the stable identifier grammar used by durable agent plan items.
pub(crate) fn ensure_valid_agent_plan_item_id(plan_item_id: &str) -> Result<(), JournalError> {
    let mut characters = plan_item_id.chars();
    let Some(first) = characters.next() else {
        return Err(JournalError::InvalidArgument("plan_item_id must not be empty".to_owned()));
    };
    if plan_item_id.chars().count() > 128
        || !first.is_ascii_alphanumeric()
        || !characters.all(|character| {
            character.is_ascii_alphanumeric() || matches!(character, '-' | '_' | '.' | ':')
        })
    {
        return Err(JournalError::InvalidArgument(
            "plan_item_id must match [A-Za-z0-9][A-Za-z0-9._:-]{0,127}".to_owned(),
        ));
    }
    Ok(())
}

fn is_known_agent_plan_status(status: &str) -> bool {
    matches!(status, "pending" | "in_progress" | "blocked" | "completed" | "cancelled")
}

fn is_terminal_agent_plan_status(status: &str) -> bool {
    matches!(status, "completed" | "cancelled")
}

fn ensure_agent_plan_priority(priority: i64) -> Result<(), JournalError> {
    if (-100..=100).contains(&priority) {
        Ok(())
    } else {
        Err(JournalError::InvalidArgument("agent plan priority must be in -100..=100".to_owned()))
    }
}

fn ensure_agent_plan_blocked_reason(
    status: &str,
    blocked_reason: Option<&str>,
) -> Result<(), JournalError> {
    if status == "blocked" && blocked_reason.is_none_or(|reason| reason.trim().is_empty()) {
        return Err(JournalError::InvalidArgument(
            "blocked agent plan item requires blocked_reason".to_owned(),
        ));
    }
    Ok(())
}

fn validate_agent_plan_transition(
    plan_item_id: &str,
    from: &str,
    to: &str,
) -> Result<(), JournalError> {
    ensure_valid_agent_plan_status(to)?;
    if from == to {
        return Ok(());
    }
    if is_terminal_agent_plan_status(from) {
        return Err(JournalError::InvalidAgentPlanTransition {
            plan_item_id: plan_item_id.to_owned(),
            from: from.to_owned(),
            to: to.to_owned(),
        });
    }
    Ok(())
}

fn agent_plan_update_event_type(status: &str) -> &'static str {
    match status {
        "blocked" => "agent.plan.blocked",
        "completed" => "agent.plan.completed",
        _ => "agent.plan.updated",
    }
}

fn ensure_valid_progress_draft_state(state: &str) -> Result<(), JournalError> {
    if is_known_progress_draft_state(state) {
        Ok(())
    } else {
        Err(JournalError::InvalidArgument(format!("unknown progress draft state: {state}")))
    }
}

fn is_known_progress_draft_state(state: &str) -> bool {
    matches!(
        state,
        "pending"
            | "running"
            | "waiting_approval"
            | "retry_scheduled"
            | "compacting"
            | "completed"
            | "failed"
            | "cancelled"
    )
}

fn is_terminal_progress_draft_state(state: &str) -> bool {
    matches!(state, "completed" | "failed" | "cancelled")
}

fn validate_progress_draft_transition(
    draft_id: &str,
    from: &str,
    to: &str,
) -> Result<(), JournalError> {
    ensure_valid_progress_draft_state(to)?;
    if from == to {
        return Ok(());
    }
    if is_terminal_progress_draft_state(from) {
        return Err(JournalError::InvalidProgressDraftTransition {
            draft_id: draft_id.to_owned(),
            from: from.to_owned(),
            to: to.to_owned(),
        });
    }
    Ok(())
}

fn progress_draft_update_event_type(state: &str) -> &'static str {
    if is_terminal_progress_draft_state(state) {
        crate::application::progress_draft::PROGRESS_DRAFT_EVENT_COMPLETED
    } else {
        crate::application::progress_draft::PROGRESS_DRAFT_EVENT_UPDATED
    }
}

fn sanitize_json_payload_field(
    raw: &str,
    field: &'static str,
    max_payload_bytes: usize,
) -> Result<String, JournalError> {
    ensure_json_field(raw, field)?;
    if raw.len() > max_payload_bytes {
        return Err(JournalError::PayloadTooLarge {
            payload_kind: field,
            actual_bytes: raw.len(),
            max_bytes: max_payload_bytes,
        });
    }
    let (sanitized, _) = sanitize_payload(raw.as_bytes())?;
    if sanitized.len() > max_payload_bytes {
        return Err(JournalError::PayloadTooLarge {
            payload_kind: field,
            actual_bytes: sanitized.len(),
            max_bytes: max_payload_bytes,
        });
    }
    Ok(sanitized)
}

fn sanitize_plan_text_field(
    raw: &str,
    key: &str,
    field: &'static str,
) -> Result<String, JournalError> {
    ensure_nonempty_field(raw, field)?;
    let sanitized = sanitize_object_text_field(key, raw)?.trim().to_owned();
    ensure_nonempty_field(sanitized.as_str(), field)?;
    Ok(sanitized)
}

fn sanitize_plan_optional_text_field(
    raw: Option<&str>,
    key: &str,
    field: &'static str,
) -> Result<Option<String>, JournalError> {
    raw.map(|value| sanitize_plan_text_field(value, key, field)).transpose()
}

fn sanitize_progress_draft_optional_text(
    raw: Option<&str>,
    key: &str,
    field: &'static str,
) -> Result<Option<String>, JournalError> {
    raw.and_then(|value| {
        let trimmed = value.trim();
        (!trimmed.is_empty()).then_some(trimmed)
    })
    .map(|value| sanitize_plan_text_field(value, key, field))
    .transpose()
}

