fn nonnegative_i64_to_u64(value: i64) -> Option<u64> {
    (value >= 0).then_some(value as u64)
}

fn map_cron_job_row(row: &rusqlite::Row<'_>) -> Result<CronJobRecord, rusqlite::Error> {
    let schedule_type_raw: String = row.get(8)?;
    let schedule_type =
        CronScheduleType::from_str(schedule_type_raw.as_str()).ok_or_else(|| {
            rusqlite::Error::FromSqlConversionFailure(
                8,
                rusqlite::types::Type::Text,
                Box::new(std::io::Error::new(
                    std::io::ErrorKind::InvalidData,
                    format!("invalid cron schedule_type value: {schedule_type_raw}"),
                )),
            )
        })?;
    let concurrency_policy_raw: String = row.get(11)?;
    let concurrency_policy = CronConcurrencyPolicy::from_str(concurrency_policy_raw.as_str())
        .ok_or_else(|| {
            rusqlite::Error::FromSqlConversionFailure(
                11,
                rusqlite::types::Type::Text,
                Box::new(std::io::Error::new(
                    std::io::ErrorKind::InvalidData,
                    format!("invalid cron concurrency_policy value: {concurrency_policy_raw}"),
                )),
            )
        })?;
    let retry_policy_json: String = row.get(12)?;
    let retry_policy: CronRetryPolicy =
        serde_json::from_str(retry_policy_json.as_str()).map_err(|error| {
            rusqlite::Error::FromSqlConversionFailure(
                12,
                rusqlite::types::Type::Text,
                Box::new(std::io::Error::new(
                    std::io::ErrorKind::InvalidData,
                    format!("invalid retry_policy_json: {error}"),
                )),
            )
        })?;
    let misfire_policy_raw: String = row.get(13)?;
    let misfire_policy =
        CronMisfirePolicy::from_str(misfire_policy_raw.as_str()).ok_or_else(|| {
            rusqlite::Error::FromSqlConversionFailure(
                13,
                rusqlite::types::Type::Text,
                Box::new(std::io::Error::new(
                    std::io::ErrorKind::InvalidData,
                    format!("invalid cron misfire_policy value: {misfire_policy_raw}"),
                )),
            )
        })?;

    Ok(CronJobRecord {
        job_id: row.get(0)?,
        name: row.get(1)?,
        prompt: row.get(2)?,
        owner_principal: row.get(3)?,
        channel: row.get(4)?,
        session_key: row.get(5)?,
        session_label: row.get(6)?,
        workdir: row.get(7)?,
        schedule_type,
        schedule_payload_json: row.get(9)?,
        enabled: row.get::<_, i64>(10)? == 1,
        concurrency_policy,
        retry_policy,
        misfire_policy,
        jitter_ms: row.get::<_, i64>(14)? as u64,
        next_run_at_unix_ms: row.get(15)?,
        last_run_at_unix_ms: row.get(16)?,
        queued_run: row.get::<_, i64>(17)? == 1,
        created_at_unix_ms: row.get(18)?,
        updated_at_unix_ms: row.get(19)?,
    })
}

fn load_cron_job_by_id(
    connection: &Connection,
    job_id: &str,
) -> Result<Option<CronJobRecord>, JournalError> {
    let mut statement = connection.prepare(
        r#"
            SELECT
                job_ulid,
                name,
                prompt,
                owner_principal,
                channel,
                session_key,
                session_label,
                workdir,
                schedule_type,
                schedule_payload_json,
                enabled,
                concurrency_policy,
                retry_policy_json,
                misfire_policy,
                jitter_ms,
                next_run_at_unix_ms,
                last_run_at_unix_ms,
                queued_run,
                created_at_unix_ms,
                updated_at_unix_ms
            FROM cron_jobs
            WHERE job_ulid = ?1
            LIMIT 1
        "#,
    )?;
    statement.query_row(params![job_id], map_cron_job_row).optional().map_err(Into::into)
}

