    #[test]
    fn delete_orchestrator_session_pin_requires_session_match() {
        let db_path = temp_db_path();
        let store = JournalStore::open(test_journal_config(db_path, false))
            .expect("journal store should open");
        let local_session_id = "01ARZ3NDEKTSV4RRFFQ69G5PN1";
        let foreign_session_id = "01ARZ3NDEKTSV4RRFFQ69G5PN2";
        let local_run_id = "01ARZ3NDEKTSV4RRFFQ69G5PR1";
        let foreign_run_id = "01ARZ3NDEKTSV4RRFFQ69G5PR2";
        upsert_orchestrator_session(&store, local_session_id);
        upsert_orchestrator_session(&store, foreign_session_id);
        start_orchestrator_run(&store, local_session_id, local_run_id);
        start_orchestrator_run(&store, foreign_session_id, foreign_run_id);
        append_tape_event(&store, local_run_id, 1);
        append_tape_event(&store, foreign_run_id, 1);

        let local_pin = store
            .create_orchestrator_session_pin(&OrchestratorSessionPinCreateRequest {
                pin_id: "01ARZ3NDEKTSV4RRFFQ69G5PP1".to_owned(),
                session_id: local_session_id.to_owned(),
                run_id: local_run_id.to_owned(),
                tape_seq: 1,
                title: "Local pin".to_owned(),
                note: None,
            })
            .expect("local pin should be created");
        let foreign_pin = store
            .create_orchestrator_session_pin(&OrchestratorSessionPinCreateRequest {
                pin_id: "01ARZ3NDEKTSV4RRFFQ69G5PP2".to_owned(),
                session_id: foreign_session_id.to_owned(),
                run_id: foreign_run_id.to_owned(),
                tape_seq: 1,
                title: "Foreign pin".to_owned(),
                note: None,
            })
            .expect("foreign pin should be created");

        let deleted_foreign = store
            .delete_orchestrator_session_pin(local_session_id, foreign_pin.pin_id.as_str())
            .expect("cross-session pin delete should query successfully");
        assert!(!deleted_foreign);
        assert_eq!(
            store
                .list_orchestrator_session_pins(foreign_session_id)
                .expect("foreign session pins should load")
                .len(),
            1
        );

        let deleted_local = store
            .delete_orchestrator_session_pin(local_session_id, local_pin.pin_id.as_str())
            .expect("local pin delete should succeed");
        assert!(deleted_local);
        assert!(store
            .list_orchestrator_session_pins(local_session_id)
            .expect("local session pins should load")
            .is_empty());
    }

    #[test]
    fn create_queued_input_can_start_as_terminal_overflow() {
        let db_path = temp_db_path();
        let store = JournalStore::open(test_journal_config(db_path, false))
            .expect("journal store should open");
        let session_id = "01ARZ3NDEKTSV4RRFFQ69G5QA1";
        let run_id = "01ARZ3NDEKTSV4RRFFQ69G5QA2";
        let queued_input_id = "01ARZ3NDEKTSV4RRFFQ69G5QA3";
        upsert_orchestrator_session(&store, session_id);
        start_orchestrator_run(&store, session_id, run_id);

        let created = store
            .create_orchestrator_queued_input(&OrchestratorQueuedInputCreateRequest {
                queued_input_id: queued_input_id.to_owned(),
                run_id: run_id.to_owned(),
                session_id: session_id.to_owned(),
                state: "overflowed".to_owned(),
                text: "queue cap reached; input was not accepted".to_owned(),
                origin_run_id: Some(run_id.to_owned()),
                queue_mode: "collect".to_owned(),
                delivery_boundary: "backlog_summary".to_owned(),
                expected_active_generation: Some(1),
                priority_lane: "normal".to_owned(),
                coalescing_group: Some("session:queue-test".to_owned()),
                overflow_summary_ref: Some("queue-summary:test".to_owned()),
                safe_boundary_flags_json: "{}".to_owned(),
                decision_reason: "queue_cap_reached_overflow_summary_required".to_owned(),
                attachments_json: "[]".to_owned(),
                queue_outcome_json: r#"{"schema_version":1}"#.to_owned(),
                accepted_at_unix_ms: None,
                policy_snapshot_json: "{}".to_owned(),
                explain_json: r#"{"accepted":false}"#.to_owned(),
            })
            .expect("overflowed queued input audit row should be created");

        assert_eq!(created.state, "overflowed");
        assert_eq!(created.accepted_at_unix_ms, None);
        assert!(created.coalesced_at_unix_ms.is_some());
        assert!(created.terminal_at_unix_ms.is_some());

        let queued_inputs =
            store.list_orchestrator_queued_inputs(session_id).expect("queued inputs should list");
        assert_eq!(queued_inputs.len(), 1);
        assert_eq!(
            queued_inputs.iter().filter(|queued| queued.state == "pending").count(),
            0,
            "overflow audit rows must not increase pending depth"
        );
    }

    #[test]
    fn queued_input_transitions_are_compare_and_set_and_terminal_once() {
        let db_path = temp_db_path();
        let store = JournalStore::open(test_journal_config(db_path, false))
            .expect("journal store should open");
        let session_id = "01ARZ3NDEKTSV4RRFFQ69G5QB1";
        let run_id = "01ARZ3NDEKTSV4RRFFQ69G5QB2";
        let queued_input_id = "01ARZ3NDEKTSV4RRFFQ69G5QB3";
        upsert_orchestrator_session(&store, session_id);
        start_orchestrator_run(&store, session_id, run_id);
        let pending = store
            .create_orchestrator_queued_input(&OrchestratorQueuedInputCreateRequest {
                queued_input_id: queued_input_id.to_owned(),
                run_id: run_id.to_owned(),
                session_id: session_id.to_owned(),
                state: QueuedInputState::Pending.as_str().to_owned(),
                text: "apply the corrected constraint".to_owned(),
                origin_run_id: Some(run_id.to_owned()),
                queue_mode: "steer".to_owned(),
                delivery_boundary: "current_run_before_provider".to_owned(),
                expected_active_generation: Some(1),
                priority_lane: "normal".to_owned(),
                coalescing_group: Some("session:queue-cas".to_owned()),
                overflow_summary_ref: None,
                safe_boundary_flags_json: "{}".to_owned(),
                decision_reason: "queue.steer.accepted".to_owned(),
                attachments_json: "[]".to_owned(),
                queue_outcome_json: r#"{"lifecycle_state":"pending"}"#.to_owned(),
                accepted_at_unix_ms: Some(1),
                policy_snapshot_json: "{}".to_owned(),
                explain_json: "{}".to_owned(),
            })
            .expect("queued input should persist");

        let claim_request = OrchestratorQueuedInputUpdateRequest {
            queued_input_id: queued_input_id.to_owned(),
            expected_state: pending.state.clone(),
            expected_revision: pending.lifecycle_revision,
            state: QueuedInputState::Claimed.as_str().to_owned(),
            claimed_active_generation: Some(1),
            overflow_summary_ref: None,
            decision_reason: Some("queue.active_run.claimed".to_owned()),
            explain_json: None,
            queue_outcome_json: Some(r#"{"lifecycle_state":"claimed"}"#.to_owned()),
        };
        let claimed = store
            .update_orchestrator_queued_input_state(&claim_request)
            .expect("pending input should be claimed");
        assert_eq!(claimed.lifecycle_revision, 1);
        assert_eq!(claimed.state, QueuedInputState::Claimed.as_str());
        assert_eq!(claimed.claimed_active_generation, Some(1));
        assert_eq!(claimed.terminal_at_unix_ms, None);

        let stale_error = store
            .update_orchestrator_queued_input_state(&claim_request)
            .expect_err("the stale claim must lose the compare-and-set race");
        assert!(matches!(
            stale_error,
            JournalError::QueuedInputTransitionConflict {
                expected_revision: 0,
                actual_revision: 1,
                ..
            }
        ));

        let injected = store
            .update_orchestrator_queued_input_state(&OrchestratorQueuedInputUpdateRequest {
                queued_input_id: queued_input_id.to_owned(),
                expected_state: claimed.state.clone(),
                expected_revision: claimed.lifecycle_revision,
                state: QueuedInputState::Injected.as_str().to_owned(),
                claimed_active_generation: None,
                overflow_summary_ref: None,
                decision_reason: Some("queue.active_run.injected".to_owned()),
                explain_json: None,
                queue_outcome_json: Some(r#"{"lifecycle_state":"injected"}"#.to_owned()),
            })
            .expect("claimed input should inject exactly once");
        assert_eq!(injected.lifecycle_revision, 2);
        assert!(injected.terminal_at_unix_ms.is_some());

        let terminal_error = store
            .update_orchestrator_queued_input_state(&OrchestratorQueuedInputUpdateRequest {
                queued_input_id: queued_input_id.to_owned(),
                expected_state: injected.state,
                expected_revision: injected.lifecycle_revision,
                state: QueuedInputState::Forwarded.as_str().to_owned(),
                claimed_active_generation: None,
                overflow_summary_ref: None,
                decision_reason: None,
                explain_json: None,
                queue_outcome_json: None,
            })
            .expect_err("a terminal queue record must never reopen or change outcome");
        assert!(matches!(terminal_error, JournalError::InvalidArgument(_)));
    }

    #[test]
    fn startup_recovery_terminalizes_orphaned_active_runs() {
        let db_path = temp_db_path();
        let store = JournalStore::open(test_journal_config(db_path, false))
            .expect("journal store should open");
        let in_progress_session_id = "01ARZ3NDEKTSV4RRFFQ69G5SR1";
        let in_progress_run_id = "01ARZ3NDEKTSV4RRFFQ69G5RR1";
        let accepted_session_id = "01ARZ3NDEKTSV4RRFFQ69G5SR2";
        let accepted_run_id = "01ARZ3NDEKTSV4RRFFQ69G5RR2";
        let done_session_id = "01ARZ3NDEKTSV4RRFFQ69G5SR3";
        let done_run_id = "01ARZ3NDEKTSV4RRFFQ69G5RR3";
        let reason = "daemon startup detected an orphaned active run";

        upsert_orchestrator_session(&store, in_progress_session_id);
        start_orchestrator_run(&store, in_progress_session_id, in_progress_run_id);
        activate_runtime_generation(
            &store,
            in_progress_session_id,
            in_progress_run_id,
            RuntimeGenerationTransitionKind::Activated,
        );
        store
            .update_orchestrator_run_state(in_progress_run_id, RunLifecycleState::InProgress, None)
            .expect("run should enter in_progress");
        store
            .append_orchestrator_tape_event(&OrchestratorTapeAppendRequest {
                run_id: in_progress_run_id.to_owned(),
                seq: 0,
                event_type: "tool_decision".to_owned(),
                payload_json: json!({
                    "proposal_id": "sleep-1",
                    "tool_name": "palyra.sleep",
                    "allowed": true,
                })
                .to_string(),
            })
            .expect("pre-crash tape event should be recorded");

        upsert_orchestrator_session(&store, accepted_session_id);
        start_orchestrator_run(&store, accepted_session_id, accepted_run_id);
        activate_runtime_generation(
            &store,
            accepted_session_id,
            accepted_run_id,
            RuntimeGenerationTransitionKind::Activated,
        );

        upsert_orchestrator_session(&store, done_session_id);
        start_orchestrator_run(&store, done_session_id, done_run_id);
        store
            .update_orchestrator_run_state(done_run_id, RunLifecycleState::Done, None)
            .expect("control run should complete");

        let report = store
            .terminalize_orphaned_orchestrator_runs_on_startup(reason)
            .expect("startup recovery should terminalize active runs");

        assert_eq!(report.terminalized_count, 2);
        assert!(report.terminalized_run_ids.contains(&in_progress_run_id.to_owned()));
        assert!(report.terminalized_run_ids.contains(&accepted_run_id.to_owned()));

        let in_progress = store
            .orchestrator_run_status_snapshot(in_progress_run_id)
            .expect("snapshot lookup should succeed")
            .expect("run should exist");
        assert_eq!(in_progress.state, RunLifecycleState::Failed.as_str());
        assert_eq!(
            in_progress.last_error.as_deref(),
            Some("interrupted run is outside the safe automatic recovery contract")
        );
        assert!(in_progress.completed_at_unix_ms.is_some());
        assert_eq!(in_progress.tape_events, 5);

        let accepted = store
            .orchestrator_run_status_snapshot(accepted_run_id)
            .expect("snapshot lookup should succeed")
            .expect("run should exist");
        assert_eq!(accepted.state, RunLifecycleState::Failed.as_str());
        assert_eq!(
            accepted.last_error.as_deref(),
            Some("interrupted run is outside the safe automatic recovery contract")
        );
        assert!(accepted.completed_at_unix_ms.is_some());
        assert_eq!(accepted.tape_events, 4);

        let done = store
            .orchestrator_run_status_snapshot(done_run_id)
            .expect("snapshot lookup should succeed")
            .expect("run should exist");
        assert_eq!(done.state, RunLifecycleState::Done.as_str());

        let lifecycle = store
            .list_run_lifecycle_events(in_progress_run_id)
            .expect("lifecycle events should be readable");
        let terminal = lifecycle.last().expect("startup recovery should append lifecycle event");
        assert_eq!(terminal.from_state, Some(RunLifecyclePhase::Running));
        assert_eq!(terminal.to_state, RunLifecyclePhase::Failed);
        assert_eq!(terminal.reason, "run.recovery.startup_orphaned");

        let in_progress_tape = store
            .orchestrator_tape(in_progress_run_id)
            .expect("startup recovery tape should be readable");
        let resume_decision = in_progress_tape
            .iter()
            .find(|event| {
                event.event_type
                    == crate::application::resume_classifier::RUN_RESUME_DECISION_RECORDED_EVENT
            })
            .expect("startup recovery should record resume classifier decision");
        assert_eq!(resume_decision.seq, 1);
        let resume_payload =
            serde_json::from_str::<serde_json::Value>(resume_decision.payload_json.as_str())
                .expect("resume decision payload should be JSON");
        assert_eq!(
            resume_payload["event"],
            crate::application::resume_classifier::RUN_RESUME_DECISION_RECORDED_EVENT
        );
        assert_eq!(resume_payload["decision"], "stale_do_not_resume");
        assert_eq!(resume_payload["reason_code"], "resume.missing_freshness_evidence");

        let replay_continuity = in_progress_tape
            .iter()
            .find(|event| {
                event.event_type
                    == crate::application::replay_continuity::REPLAY_CONTINUITY_EVENT_COMPLETED
            })
            .expect("startup recovery should record replay continuity projection");
        assert_eq!(replay_continuity.seq, 2);
        let replay_payload =
            serde_json::from_str::<serde_json::Value>(replay_continuity.payload_json.as_str())
                .expect("replay continuity payload should be JSON");
        assert_eq!(
            replay_payload["event"],
            crate::application::replay_continuity::REPLAY_CONTINUITY_EVENT_COMPLETED
        );
        assert_eq!(replay_payload["rollout_mode"], "observe_only");
        assert_eq!(replay_payload["provider_transcript"]["decision"], "block_replay");
        assert_eq!(
            replay_payload["provider_transcript"]["reason_code"],
            "replay.resume_forbids_replay"
        );
        assert_eq!(replay_payload["redaction_level"], "none");

        let recovery = in_progress_tape
            .iter()
            .find(|event| event.event_type == "run.recovery")
            .expect("startup recovery should append recovery evidence");
        assert_eq!(recovery.seq, 3);
        let recovery_payload =
            serde_json::from_str::<serde_json::Value>(recovery.payload_json.as_str())
                .expect("recovery payload should be JSON");
        assert_eq!(recovery_payload["event"], "run.recovery");
        assert_eq!(recovery_payload["recovery_kind"], "startup_orphaned_active_run");
        assert_eq!(recovery_payload["recovery_state"], "do_not_resume");
        assert_eq!(recovery_payload["previous_state"], RunLifecycleState::InProgress.as_str());
        assert_eq!(recovery_payload["terminal_state"], RunLifecycleState::Failed.as_str());
        assert_eq!(recovery_payload["resume_decision"], "stale_do_not_resume");
        assert_eq!(recovery_payload["resume_reason_code"], "resume.missing_freshness_evidence");
        assert_eq!(
            recovery_payload["replay_continuity"]["event_type"],
            crate::application::replay_continuity::REPLAY_CONTINUITY_EVENT_COMPLETED
        );
        assert_eq!(
            recovery_payload["replay_continuity"]["provider_transcript_decision"],
            "block_replay"
        );
        assert_eq!(recovery_payload["reason"], reason);
        let terminal_status = in_progress_tape.last().expect("terminal status should be last");
        assert_eq!(terminal_status.seq, 4);
        assert_eq!(terminal_status.event_type, "status");
        let terminal_status_payload =
            serde_json::from_str::<serde_json::Value>(terminal_status.payload_json.as_str())
                .expect("terminal status should be JSON");
        assert_eq!(terminal_status_payload["kind"], "failed");
        assert_eq!(terminal_status_payload["lifecycle_state"], "failed");
        assert_eq!(terminal_status_payload["reason_code"], "run.recovery.startup_orphaned");

        let accepted_tape = store
            .orchestrator_tape(accepted_run_id)
            .expect("accepted recovery tape should be readable");
        assert_eq!(accepted_tape.len(), 4);
        assert_eq!(accepted_tape[0].seq, 0);
        assert_eq!(
            accepted_tape[0].event_type,
            crate::application::resume_classifier::RUN_RESUME_DECISION_RECORDED_EVENT
        );
        assert_eq!(accepted_tape[1].seq, 1);
        assert_eq!(
            accepted_tape[1].event_type,
            crate::application::replay_continuity::REPLAY_CONTINUITY_EVENT_COMPLETED
        );
        assert_eq!(accepted_tape[2].seq, 2);
        assert_eq!(accepted_tape[2].event_type, "run.recovery");
        assert_eq!(accepted_tape[3].seq, 3);
        assert_eq!(accepted_tape[3].event_type, "status");

        let connection = store.connection.lock().expect("connection lock should not be poisoned");
        for run_id in [in_progress_run_id, accepted_run_id] {
            let terminal_event_count: i64 = connection
                .query_row(
                    "SELECT COUNT(*) FROM runtime_events_v2 WHERE run_ulid = ?1 AND terminal = 1",
                    params![run_id],
                    |row| row.get(0),
                )
                .expect("terminal runtime event should count");
            let active_generation_count: i64 = connection
                .query_row(
                    "SELECT COUNT(*) FROM runtime_generation_leases WHERE run_ulid = ?1 AND lane = 'run'",
                    params![run_id],
                    |row| row.get(0),
                )
                .expect("active generation should count");
            assert_eq!(terminal_event_count, 1);
            assert_eq!(active_generation_count, 0);
        }
    }

    #[test]
    fn startup_recovery_never_regenerates_a_committed_final_output() {
        use palyra_common::runtime_contracts::RuntimeTerminalOutcome;

        use crate::journal::runtime_finalization::{
            DeliveryArbitrationActionV2, DeliveryArbitrationDecisionV2,
            FinalOutputArtifactDescriptor,
        };
        use crate::journal::StartupRecoveryActuationKind;

        let db_path = temp_db_path();
        let store = JournalStore::open(test_journal_config(db_path, false))
            .expect("journal store should open");
        let session_id = "01ARZ3NDEKTSV4RRFFQ69G5SF1";
        let run_id = "01ARZ3NDEKTSV4RRFFQ69G5RF1";
        upsert_orchestrator_session(&store, session_id);
        start_orchestrator_run(&store, session_id, run_id);
        let lease = store
            .active_runtime_generation_for_run(run_id, RuntimeGenerationLane::Run)
            .expect("run generation should load")
            .expect("run generation should be active");
        let content_sha256 = "a".repeat(64);
        let descriptor = FinalOutputArtifactDescriptor {
            artifact_id: "01ARZ3NDEKTSV4RRFFQ69G5AF1".to_owned(),
            session_id: session_id.to_owned(),
            run_id: run_id.to_owned(),
            run_generation: lease.generation,
            run_lease_id: lease.lease_id.as_str().to_owned(),
            terminal_outcome: RuntimeTerminalOutcome::Completed,
            content_sha256: content_sha256.clone(),
            projection_sha256: content_sha256.clone(),
            user_visible: false,
            verification_evidence: Vec::new(),
            missing_artifacts: Vec::new(),
            active_process_state: Vec::new(),
            reason_code: RuntimeTerminalOutcome::Completed.reason_code().to_owned(),
            committed_at_unix_ms: 0,
        };
        let decision = DeliveryArbitrationDecisionV2 {
            artifact_id: descriptor.artifact_id.clone(),
            session_id: session_id.to_owned(),
            run_id: run_id.to_owned(),
            run_generation: lease.generation,
            parent_run_id: None,
            descendant_run_ids: Vec::new(),
            action: DeliveryArbitrationActionV2::Suppress,
            destination_binding_sha256: None,
            delivery_intent_id: None,
            connector_id: None,
            outbox_envelope_id: None,
            content_sha256,
            outbound_request_sha256: None,
            dedupe_key: None,
            outbound_request: None,
            reason_code: "runtime.delivery.arbitration_suppress".to_owned(),
            decided_at_unix_ms: 0,
        };
        store
            .commit_runtime_final_output_with_arbitration(&descriptor, &decision)
            .expect("final artifact and arbitration should commit");

        let report = store
            .terminalize_orphaned_orchestrator_runs_on_startup(
                "daemon startup detected a finalized orphan",
            )
            .expect("startup recovery should reconcile the finalized run");

        assert_eq!(report.continuation_queued_count, 0);
        assert_eq!(report.confirmation_required_count, 0);
        assert_eq!(
            report.actions.first().map(|action| action.actuation_kind),
            Some(StartupRecoveryActuationKind::DoNotResume)
        );
        let tape = store.orchestrator_tape(run_id).expect("recovery tape should load");
        let resume = tape
            .iter()
            .find(|event| {
                event.event_type
                    == crate::application::resume_classifier::RUN_RESUME_DECISION_RECORDED_EVENT
            })
            .expect("resume classifier evidence should exist");
        let payload: serde_json::Value = serde_json::from_str(resume.payload_json.as_str())
            .expect("resume evidence should parse");
        assert_eq!(payload["decision"], "terminal_do_not_resume");
        assert_eq!(payload["reason_code"], "resume.terminal_run_state");
    }

    #[test]
    fn startup_recovery_queues_one_real_continuation_for_safe_read_only_wait() {
        let db_path = temp_db_path();
        let store = JournalStore::open(test_journal_config(db_path, false))
            .expect("journal store should open");
        let session_id = "01ARZ3NDEKTSV4RRFFQ69G5SC1";
        let run_id = "01ARZ3NDEKTSV4RRFFQ69G5RC1";
        upsert_orchestrator_session(&store, session_id);
        start_orchestrator_run(&store, session_id, run_id);
        activate_runtime_generation(
            &store,
            session_id,
            run_id,
            RuntimeGenerationTransitionKind::Activated,
        );
        store
            .update_orchestrator_run_state(run_id, RunLifecycleState::InProgress, None)
            .expect("run should enter in_progress");
        for (seq, event_type, payload_json) in [
            (0, "provider_turn_output", json!({"finish_reason": "tool_calls"})),
            (
                1,
                "tool_proposal",
                json!({
                    "proposal_id": "read-1",
                    "tool_name": "palyra.fs.read_file",
                }),
            ),
            (
                2,
                "tool_decision",
                json!({
                    "proposal_id": "read-1",
                    "decision": "allow",
                }),
            ),
        ] {
            store
                .append_orchestrator_tape_event(&OrchestratorTapeAppendRequest {
                    run_id: run_id.to_owned(),
                    seq,
                    event_type: event_type.to_owned(),
                    payload_json: payload_json.to_string(),
                })
                .expect("pre-crash evidence should persist");
        }

        let report = store
            .terminalize_orphaned_orchestrator_runs_on_startup("startup_test")
            .expect("safe recovery should actuate");
        assert_eq!(report.scanned_count, 1);
        assert_eq!(report.continuation_queued_count, 1);
        assert_eq!(report.confirmation_required_count, 0);
        let descriptor =
            report.continuation_descriptors.first().expect("continuation should be described");
        assert_eq!(descriptor.recovered_from_run_id, run_id);
        assert_eq!(descriptor.session_id, session_id);
        assert_eq!(descriptor.budget_tokens, 4_096);
        assert_ne!(descriptor.continuation_run_id, run_id);

        let task = store
            .get_orchestrator_background_task(descriptor.continuation_task_id.as_str())
            .expect("continuation task should load")
            .expect("continuation task should exist");
        assert_eq!(task.state, AuxiliaryTaskState::Queued.as_str());
        assert_eq!(task.parent_run_id.as_deref(), Some(run_id));
        assert_eq!(
            task.planned_child_run_id.as_deref(),
            Some(descriptor.continuation_run_id.as_str())
        );
        assert!(task.target_run_id.is_none());
        assert_eq!(task.owner_principal, "user:ops");
        assert_eq!(task.channel.as_deref(), Some("cli"));
        assert_eq!(task.max_attempts, 1);

        let second = store
            .terminalize_orphaned_orchestrator_runs_on_startup("second_startup")
            .expect("second startup should be idempotent");
        assert_eq!(second.scanned_count, 0);
        assert_eq!(second.continuation_queued_count, 0);
        let connection = store.connection.lock().expect("connection lock should be available");
        let action_count: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM startup_recovery_actions_v1 WHERE original_run_ulid = ?1",
                params![run_id],
                |row| row.get(0),
            )
            .expect("recovery action should count");
        let continuation_count: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM orchestrator_background_tasks WHERE parent_run_ulid = ?1 AND task_kind = 'background_prompt'",
                params![run_id],
                |row| row.get(0),
            )
            .expect("continuation tasks should count");
        assert_eq!(action_count, 1);
        assert_eq!(continuation_count, 1);
    }

    #[test]
    fn startup_recovery_turns_unknown_mutation_into_durable_confirmation() {
        let db_path = temp_db_path();
        let store = JournalStore::open(test_journal_config(db_path, false))
            .expect("journal store should open");
        let session_id = "01ARZ3NDEKTSV4RRFFQ69G5SC2";
        let run_id = "01ARZ3NDEKTSV4RRFFQ69G5RC2";
        upsert_orchestrator_session(&store, session_id);
        start_orchestrator_run(&store, session_id, run_id);
        activate_runtime_generation(
            &store,
            session_id,
            run_id,
            RuntimeGenerationTransitionKind::Activated,
        );
        store
            .update_orchestrator_run_state(run_id, RunLifecycleState::InProgress, None)
            .expect("run should enter in_progress");
        for (seq, event_type, payload_json) in [
            (0, "provider_turn_output", json!({"finish_reason": "tool_calls"})),
            (
                1,
                "tool_proposal",
                json!({
                    "proposal_id": "patch-1",
                    "tool_name": "palyra.fs.apply_patch",
                }),
            ),
            (
                2,
                "tool_decision",
                json!({
                    "proposal_id": "patch-1",
                    "decision": "allow",
                }),
            ),
        ] {
            store
                .append_orchestrator_tape_event(&OrchestratorTapeAppendRequest {
                    run_id: run_id.to_owned(),
                    seq,
                    event_type: event_type.to_owned(),
                    payload_json: payload_json.to_string(),
                })
                .expect("pre-crash evidence should persist");
        }

        let report = store
            .terminalize_orphaned_orchestrator_runs_on_startup("startup_test")
            .expect("ambiguous recovery should actuate");
        assert_eq!(report.continuation_queued_count, 0);
        assert_eq!(report.confirmation_required_count, 1);
        let confirmation_id = report.confirmation_ids.first().expect("approval should be durable");
        let connection = store.connection.lock().expect("connection lock should be available");
        let approval = connection
            .query_row(
                r#"
                    SELECT principal, device_id, channel, subject_type, subject_id, decision
                    FROM approvals
                    WHERE approval_ulid = ?1
                "#,
                params![confirmation_id],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, String>(1)?,
                        row.get::<_, Option<String>>(2)?,
                        row.get::<_, String>(3)?,
                        row.get::<_, String>(4)?,
                        row.get::<_, Option<String>>(5)?,
                    ))
                },
            )
            .expect("approval should load");
        assert_eq!(approval.0, "user:ops");
        assert_eq!(approval.2.as_deref(), Some("cli"));
        assert_eq!(approval.3, "startup_recovery");
        assert_eq!(approval.4, run_id);
        assert!(approval.5.is_none());
        let continuation_count: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM orchestrator_background_tasks WHERE parent_run_ulid = ?1",
                params![run_id],
                |row| row.get(0),
            )
            .expect("continuation tasks should count");
        assert_eq!(continuation_count, 0);
    }

    #[test]
    fn startup_recovery_fails_closed_orphaned_in_process_background_tasks() {
        let db_path = temp_db_path();
        let store = JournalStore::open(test_journal_config(db_path, false))
            .expect("journal store should open");
        let session_id = "01ARZ3NDEKTSV4RRFFQ69G5BT1";
        let summary_task_id = "01ARZ3NDEKTSV4RRFFQ69G5BT2";
        let reflection_task_id = "01ARZ3NDEKTSV4RRFFQ69G5BT3";
        let cancel_requested_task_id = "01ARZ3NDEKTSV4RRFFQ69G5BT4";
        let queued_task_id = "01ARZ3NDEKTSV4RRFFQ69G5BT6";
        let reason = "daemon startup detected an orphaned in-process background task";
        upsert_orchestrator_session(&store, session_id);

        for (task_id, task_kind) in [
            (summary_task_id, AuxiliaryTaskKind::Summary),
            (reflection_task_id, AuxiliaryTaskKind::PostRunReflection),
            (cancel_requested_task_id, AuxiliaryTaskKind::Classification),
            (queued_task_id, AuxiliaryTaskKind::Summary),
        ] {
            store
                .create_orchestrator_background_task(&OrchestratorBackgroundTaskCreateRequest {
                    task_id: task_id.to_owned(),
                    task_kind: task_kind.as_str().to_owned(),
                    session_id: session_id.to_owned(),
                    child_session_id: None,
                    parent_run_id: None,
                    target_run_id: None,
                    planned_child_run_id: None,
                    queued_input_id: None,
                    owner_principal: "user:ops".to_owned(),
                    device_id: "01ARZ3NDEKTSV4RRFFQ69G5FAV".to_owned(),
                    channel: Some("cli".to_owned()),
                    state: AuxiliaryTaskState::Queued.as_str().to_owned(),
                    priority: 0,
                    max_attempts: 1,
                    budget_tokens: 128,
                    delegation: None,
                    cancellation_context: None,
                    not_before_unix_ms: None,
                    expires_at_unix_ms: None,
                    notification_target_json: None,
                    input_text: Some("test task".to_owned()),
                    payload_json: None,
                })
                .expect("background task should be created");
        }
        for task_id in [summary_task_id, reflection_task_id, cancel_requested_task_id] {
            store
                .claim_orchestrator_background_task(&OrchestratorBackgroundTaskClaimRequest {
                    task_id: task_id.to_owned(),
                    expected_revision: 0,
                    started_at_unix_ms: 1,
                })
                .expect("background task should enter running");
        }
        store
            .update_orchestrator_background_task(&OrchestratorBackgroundTaskUpdateRequest {
                task_id: cancel_requested_task_id.to_owned(),
                expected_revision: 1,
                state: Some(AuxiliaryTaskState::CancelRequested.as_str().to_owned()),
                ..Default::default()
            })
            .expect("background task should enter cancel-requested state");

        let report = store
            .reconcile_orphaned_background_tasks_on_startup(reason)
            .expect("startup task recovery should succeed");
        assert_eq!(report.recovered_count, 0);
        assert_eq!(report.failed_count, 3);
        assert_eq!(
            report.failed_task_ids,
            vec![
                summary_task_id.to_owned(),
                reflection_task_id.to_owned(),
                cancel_requested_task_id.to_owned(),
            ]
        );

        for task_id in [summary_task_id, reflection_task_id, cancel_requested_task_id] {
            let task = store
                .get_orchestrator_background_task(task_id)
                .expect("background task should load")
                .expect("background task should exist");
            assert_eq!(task.state, AuxiliaryTaskState::Failed.as_str());
            assert_eq!(task.attempt_count, 1);
            let expected_revision = if task_id == cancel_requested_task_id { 3 } else { 2 };
            assert_eq!(task.revision, expected_revision);
            assert_eq!(task.last_error.as_deref(), Some(reason));
            assert!(task.completed_at_unix_ms.is_some());
            let result = serde_json::from_str::<Value>(
                task.result_json.as_deref().expect("recovery result should persist"),
            )
            .expect("recovery result should be JSON");
            assert_eq!(result["recovery_state"], "manual_retry_required");
            assert_eq!(result["reason_code"], "background_task.recovery.startup_orphaned");
            let expected_previous_state = if task_id == cancel_requested_task_id {
                AuxiliaryTaskState::CancelRequested.as_str()
            } else {
                AuxiliaryTaskState::Running.as_str()
            };
            assert_eq!(result["previous_state"], expected_previous_state);
        }

        let queued = store
            .get_orchestrator_background_task(queued_task_id)
            .expect("queued task should load")
            .expect("queued task should exist");
        assert_eq!(queued.state, AuxiliaryTaskState::Queued.as_str());
        assert_eq!(queued.attempt_count, 0);

        let second = store
            .reconcile_orphaned_background_tasks_on_startup(reason)
            .expect("startup task recovery should be idempotent");
        assert_eq!(second, OrchestratorStartupBackgroundTaskRecoveryReport::default());
    }

