    #[test]
    fn cron_run_start_finalize_and_active_lookup() {
        let db_path = temp_db_path();
        let store = JournalStore::open(test_journal_config(db_path, false))
            .expect("journal store should open");
        let job = store
            .create_cron_job(&sample_cron_job_request("01ARZ3NDEKTSV4RRFFQ69G5FBC"))
            .expect("cron job should be inserted");
        upsert_orchestrator_session(&store, "01ARZ3NDEKTSV4RRFFQ69G5FAW");

        store
            .start_cron_run(&CronRunStartRequest {
                run_id: "01ARZ3NDEKTSV4RRFFQ69G5FBD".to_owned(),
                job_id: job.job_id.clone(),
                attempt: 1,
                session_id: Some("01ARZ3NDEKTSV4RRFFQ69G5FAW".to_owned()),
                orchestrator_run_id: Some("01ARZ3NDEKTSV4RRFFQ69G5FAX".to_owned()),
                status: CronRunStatus::Running,
                error_kind: None,
                error_message_redacted: None,
            })
            .expect("cron run start should persist");
        let started_job = store
            .cron_job(job.job_id.as_str())
            .expect("cron job lookup should succeed")
            .expect("cron job should exist after run start");
        let started_last_run_at =
            started_job.last_run_at_unix_ms.expect("cron run start should update job last_run_at");

        let active = store
            .active_cron_run_for_job(job.job_id.as_str())
            .expect("active cron run query should succeed")
            .expect("active run should exist");
        assert_eq!(active.status, CronRunStatus::Running);

        store
            .finalize_cron_run(&CronRunFinalizeRequest {
                run_id: "01ARZ3NDEKTSV4RRFFQ69G5FBD".to_owned(),
                status: CronRunStatus::Succeeded,
                error_kind: None,
                error_message_redacted: None,
                model_tokens_in: 11,
                model_tokens_out: 7,
                tool_calls: 2,
                tool_denies: 1,
                orchestrator_run_id: Some("01ARZ3NDEKTSV4RRFFQ69G5FAX".to_owned()),
                session_id: Some("01ARZ3NDEKTSV4RRFFQ69G5FAW".to_owned()),
            })
            .expect("cron run finalize should persist");
        store
            .set_cron_job_next_run(job.job_id.as_str(), Some(1_730_000_180_000), None)
            .expect("next run update without last-run timestamp should persist");
        let next_only_job = store
            .cron_job(job.job_id.as_str())
            .expect("cron job lookup should succeed")
            .expect("cron job should exist after next-run update");
        assert_eq!(
            next_only_job.last_run_at_unix_ms,
            Some(started_last_run_at),
            "schedule advancement alone must not synthesize a last-run timestamp"
        );

        store
            .set_cron_job_next_run(
                job.job_id.as_str(),
                Some(1_730_000_120_000),
                Some(1_730_000_090_000),
            )
            .expect("next run metadata should update");

        let finalized = store
            .cron_run("01ARZ3NDEKTSV4RRFFQ69G5FBD")
            .expect("cron run lookup should succeed")
            .expect("cron run should exist");
        assert_eq!(finalized.status, CronRunStatus::Succeeded);
        assert_eq!(finalized.model_tokens_in, 11);
        assert_eq!(finalized.tool_denies, 1);

        let listed = store
            .list_cron_runs(CronRunsListFilter {
                job_id: Some(job.job_id.as_str()),
                owner_principal: None,
                after_run_id: None,
                limit: 5,
            })
            .expect("cron runs listing should succeed");
        assert_eq!(listed.len(), 1);
        assert_eq!(listed[0].run_id, "01ARZ3NDEKTSV4RRFFQ69G5FBD");
    }

    #[test]
    fn cron_run_start_rejects_second_active_for_forbid_policy() {
        let db_path = temp_db_path();
        let store = JournalStore::open(test_journal_config(db_path, false))
            .expect("journal store should open");
        let job = store
            .create_cron_job(&sample_cron_job_request("01ARZ3NDEKTSV4RRFFQ69G5FC0"))
            .expect("cron job should be inserted");

        store
            .start_cron_run(&CronRunStartRequest {
                run_id: "01ARZ3NDEKTSV4RRFFQ69G5FC1".to_owned(),
                job_id: job.job_id.clone(),
                attempt: 1,
                session_id: None,
                orchestrator_run_id: None,
                status: CronRunStatus::Accepted,
                error_kind: None,
                error_message_redacted: None,
            })
            .expect("first active cron run should persist");

        let error = store
            .start_cron_run(&CronRunStartRequest {
                run_id: "01ARZ3NDEKTSV4RRFFQ69G5FC2".to_owned(),
                job_id: job.job_id.clone(),
                attempt: 1,
                session_id: None,
                orchestrator_run_id: None,
                status: CronRunStatus::Running,
                error_kind: None,
                error_message_redacted: None,
            })
            .expect_err("second active cron run should be rejected atomically");
        assert!(matches!(
            error,
            JournalError::CronRunAlreadyActive {
                job_id,
                active_run_id,
                requested_run_id
            } if job_id == job.job_id
                && active_run_id == "01ARZ3NDEKTSV4RRFFQ69G5FC1"
                && requested_run_id == "01ARZ3NDEKTSV4RRFFQ69G5FC2"
        ));

        store
            .start_cron_run(&CronRunStartRequest {
                run_id: "01ARZ3NDEKTSV4RRFFQ69G5FC3".to_owned(),
                job_id: job.job_id.clone(),
                attempt: 1,
                session_id: None,
                orchestrator_run_id: None,
                status: CronRunStatus::Skipped,
                error_kind: Some("concurrency_forbid".to_owned()),
                error_message_redacted: Some(
                    "concurrency policy forbids overlapping runs".to_owned(),
                ),
            })
            .expect("terminal concurrency audit row should persist while active");
    }

