    #[test]
    fn memory_search_respects_scope_for_principal_channel_and_session_queries() {
        let db_path = temp_db_path();
        let store = JournalStore::open(test_journal_config(db_path, false))
            .expect("journal store should open");
        let session_id = "01ARZ3NDEKTSV4RRFFQ69G5FAS";
        store
            .create_memory_item(&sample_memory_request(
                "01ARZ3NDEKTSV4RRFFQ69G5FE1",
                "user:ops",
                None,
                None,
                MemorySource::Manual,
                "E2E durable preference: use TypeScript Vitest reports.",
            ))
            .expect("principal memory item should be created");
        store
            .create_memory_item(&sample_memory_request(
                "01ARZ3NDEKTSV4RRFFQ69G5FE2",
                "user:ops",
                Some("cli"),
                None,
                MemorySource::Manual,
                "CLI channel preference: keep local smoke checks short.",
            ))
            .expect("channel memory item should be created");
        store
            .create_memory_item(&sample_memory_request(
                "01ARZ3NDEKTSV4RRFFQ69G5FE3",
                "user:ops",
                Some("cli"),
                Some(session_id),
                MemorySource::Manual,
                "Session run note: rollback checklist captured in prior session.",
            ))
            .expect("session memory item should be created");

        let session_hits = store
            .search_memory(&MemorySearchRequest {
                principal: "user:ops".to_owned(),
                channel: Some("cli".to_owned()),
                session_id: Some(session_id.to_owned()),
                query: "TypeScript Vitest reports".to_owned(),
                top_k: 5,
                min_score: 0.0,
                tags: Vec::new(),
                sources: Vec::new(),
            })
            .expect("session memory search should succeed");
        assert!(
            session_hits.iter().any(|hit| hit.item.memory_id == "01ARZ3NDEKTSV4RRFFQ69G5FE1"),
            "session-scoped searches should include principal-scoped durable memory"
        );

        let principal_hits = store
            .search_memory(&MemorySearchRequest {
                principal: "user:ops".to_owned(),
                channel: None,
                session_id: None,
                query: "local smoke checks".to_owned(),
                top_k: 5,
                min_score: 0.0,
                tags: Vec::new(),
                sources: Vec::new(),
            })
            .expect("principal memory search should succeed");
        assert!(
            !principal_hits.iter().any(|hit| hit.item.memory_id == "01ARZ3NDEKTSV4RRFFQ69G5FE2"),
            "principal-wide searches must not include channel-scoped memory"
        );

        let principal_session_hits = store
            .search_memory(&MemorySearchRequest {
                principal: "user:ops".to_owned(),
                channel: None,
                session_id: None,
                query: "rollback checklist".to_owned(),
                top_k: 5,
                min_score: 0.0,
                tags: Vec::new(),
                sources: Vec::new(),
            })
            .expect("principal memory search should succeed");
        assert!(
            !principal_session_hits
                .iter()
                .any(|hit| hit.item.memory_id == "01ARZ3NDEKTSV4RRFFQ69G5FE3"),
            "principal-wide searches must not include session-scoped memory"
        );
    }

