    #[test]
    fn memory_vector_branch_rejects_weak_unseeded_similarity() {
        let db_path = temp_db_path();
        let store = JournalStore::open_with_memory_embedding_provider(
            test_journal_config(db_path, false),
            Arc::new(FixedMemoryEmbeddingProvider {
                model_name: "test-vector-branch-v1",
                dimensions: 4,
                vector: vec![1.0, 0.0, 0.0, 0.0],
            }),
        )
        .expect("journal store should open");
        let memory_id = "01ARZ3NDEKTSV4RRFFQ69G5VF2";
        store
            .create_memory_item(&sample_memory_request(
                memory_id,
                "user:ops",
                Some("cli"),
                None,
                MemorySource::Manual,
                "private billing credentials rotation notes",
            ))
            .expect("memory item should be created");

        let weak_vector =
            encode_vector_blob(&[(MIN_VECTOR_ONLY_COSINE_SIMILARITY / 10.0) as f32, 1.0, 0.0, 0.0]);
        let guard = store.connection.lock().expect("connection lock should not be poisoned");
        guard
            .execute(
                r#"
                    UPDATE memory_vectors
                    SET vector_blob = ?1, embedding_vector = ?1
                    WHERE memory_ulid = ?2
                "#,
                params![weak_vector, memory_id],
            )
            .expect("memory vector fixture should be weakened");
        drop(guard);

        let request = MemorySearchRequest {
            principal: "user:ops".to_owned(),
            channel: Some("cli".to_owned()),
            session_id: None,
            query: "hydraulic quantum pastry".to_owned(),
            top_k: 4,
            min_score: 0.0,
            tags: Vec::new(),
            sources: Vec::new(),
        };
        let candidates = store
            .search_memory_candidates(&request)
            .expect("candidate memory search should succeed");
        assert!(
            candidates.iter().all(|candidate| candidate.item.memory_id != memory_id),
            "weak vector-only similarity should not surface unrelated memory without an FTS seed"
        );
    }

    #[test]
    fn memory_embeddings_status_guides_hash_fallback_recovery() {
        let db_path = temp_db_path();
        let store = JournalStore::open_with_memory_embedding_runtime(
            test_journal_config(db_path, false),
            Arc::new(HashMemoryEmbeddingProvider::default()),
            MemoryEmbeddingsRuntimeProfile {
                posture: MemoryEmbeddingsPosture::DegradedConfigFallback,
                desired_model_id: None,
                active_model_id: HashMemoryEmbeddingProvider::default().model_name().to_owned(),
                active_dims: 1_536,
                degraded_reason_code: Some("embeddings_model_not_configured".to_owned()),
                warning: Some(
                    "retrieval embeddings defaulted to hash fallback because no embeddings-capable provider or model is configured"
                        .to_owned(),
                ),
                production_default_active: false,
                backfill_strategy: "incremental".to_owned(),
                batch_limit: 64,
                request_timeout_ms: 15_000,
                retry_max: 2,
            },
        )
        .expect("journal store should open");

        let status =
            store.memory_embeddings_status().expect("embedding status should be available");

        assert_eq!(status.quality, "degraded_hash_fallback");
        assert_eq!(status.degraded_reason_code.as_deref(), Some("embeddings_model_not_configured"));
        let remediation = status.remediation.as_deref().expect("remediation should be present");
        assert!(remediation.contains("palyra models set-embeddings <model>"), "{remediation}");
        assert!(remediation.contains("palyra memory index --until-complete"), "{remediation}");
    }

